import React, { useState } from 'react';
import "../../Styles/pages/CheckoutPage.css";
import { useGlobal } from '../context/GlobalContext';
import { navigate } from 'gatsby';
import stripeLogo from "../../../static/logo/stripe.png";



const usStates = [
  "Alabama", "Alaska", "Arizona", "Arkansas", "California", "Colorado", "Connecticut", "Delaware",
  "Florida", "Georgia", "Hawaii", "Idaho", "Illinois", "Indiana", "Iowa", "Kansas", "Kentucky",
  "Louisiana", "Maine", "Maryland", "Massachusetts", "Michigan", "Minnesota", "Mississippi",
  "Missouri", "Montana", "Nebraska", "Nevada", "New Hampshire", "New Jersey", "New Mexico",
  "New York", "North Carolina", "North Dakota", "Ohio", "Oklahoma", "Oregon", "Pennsylvania",
  "Rhode Island", "South Carolina", "South Dakota", "Tennessee", "Texas", "Utah", "Vermont",
  "Virginia", "Washington", "West Virginia", "Wisconsin", "Wyoming"
];

const stateToAbbreviation: any = {
  "Alabama": "AL", "Alaska": "AK", "Arizona": "AZ", "Arkansas": "AR", "California": "CA",
  "Colorado": "CO", "Connecticut": "CT", "Delaware": "DE", "Florida": "FL", "Georgia": "GA",
  "Hawaii": "HI", "Idaho": "ID", "Illinois": "IL", "Indiana": "IN", "Iowa": "IA", "Kansas": "KS",
  "Kentucky": "KY", "Louisiana": "LA", "Maine": "ME", "Maryland": "MD", "Massachusetts": "MA",
  "Michigan": "MI", "Minnesota": "MN", "Mississippi": "MS", "Missouri": "MO", "Montana": "MT",
  "Nebraska": "NE", "Nevada": "NV", "New Hampshire": "NH", "New Jersey": "NJ", "New Mexico": "NM",
  "New York": "NY", "North Carolina": "NC", "North Dakota": "ND", "Ohio": "OH", "Oklahoma": "OK",
  "Oregon": "OR", "Pennsylvania": "PA", "Rhode Island": "RI", "South Carolina": "SC",
  "South Dakota": "SD", "Tennessee": "TN", "Texas": "TX", "Utah": "UT", "Vermont": "VT",
  "Virginia": "VA", "Washington": "WA", "West Virginia": "WV", "Wisconsin": "WI", "Wyoming": "WY"
};

const abbreviationToState: any = {
  "AL": "Alabama", "AK": "Alaska", "AZ": "Arizona", "AR": "Arkansas", "CA": "California",
  "CO": "Colorado", "CT": "Connecticut", "DE": "Delaware", "FL": "Florida", "GA": "Georgia",
  "HI": "Hawaii", "ID": "Idaho", "IL": "Illinois", "IN": "Indiana", "IA": "Iowa", "KS": "Kansas",
  "KY": "Kentucky", "LA": "Louisiana", "ME": "Maine", "MD": "Maryland", "MA": "Massachusetts",
  "MI": "Michigan", "MN": "Minnesota", "MS": "Mississippi", "MO": "Missouri", "MT": "Montana",
  "NE": "Nebraska", "NV": "Nevada", "NH": "New Hampshire", "NJ": "New Jersey", "NM": "New Mexico",
  "NY": "New York", "NC": "North Carolina", "ND": "North Dakota", "OH": "Ohio", "OK": "Oklahoma",
  "OR": "Oregon", "PA": "Pennsylvania", "RI": "Rhode Island", "SC": "South Carolina",
  "SD": "South Dakota", "TN": "Tennessee", "TX": "Texas", "UT": "Utah", "VT": "Vermont",
  "VA": "Virginia", "WA": "Washington", "WV": "West Virginia", "WI": "Wisconsin", "WY": "Wyoming"
};
function convertStateNameToAbbreviation(stateName: any) {
  if (abbreviationToState[stateName]) return stateName;
  return stateToAbbreviation[stateName] || null;
}




function CheckoutPageTest({ test, manual }: any) {
  const MANUAL = true;
  const IS_TEST = test;
  const formDataDefault = IS_TEST ? {
    firstName: 'Nathan',
    lastName: 'Neuhaus',
    state: 'Washington',
    city: 'Everett',
    zipCode: '98208',
    address: '14529 56th ave SE',
    address_2: '',
    phone: '4253370363',
    email: 'nathanneuhaus@gmail.com',
    createAccount: false,
    shipToDifferent: false,
    secondary: { city: '', zipCode: '', address: '' }
  } : {
    firstName: '', lastName: '', state: '', city: '', zipCode: '',
    address: '', address_2: '', phone: '', email: '',
    createAccount: false, shipToDifferent: false,
    secondary: { city: '', zipCode: '', address: '' }
  };

  const { state } = useGlobal();
  const [formData, setFormData] = useState(formDataDefault);
  const [errors, setErrors] = useState({});
  const [payload, setPayload] = useState(true);
  const [confirmingAddress, setConfirmingAddress] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [buttonDisabled, setButtonDisabled] = useState(false);

  const [addressConfirmed, setAddressConfirmed] = useState(MANUAL);

  const manualShipping = MANUAL
    ? state.cart.reduce((sum, item) => sum + 17 * (item.quantity || 1), 0)
    : 0;
  const [shippingCost, setShippingCost] = useState(manualShipping);

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    if (name.startsWith("secondary.")) {
      const key = name.split(".")[1];
      setFormData(prev => ({
        ...prev,
        secondary: { ...prev.secondary, [key]: value }
      }));
    } else {
      setFormData(prev => ({
        ...prev,
        [name]: type === 'checkbox' ? checked : value
      }));
    }
  };

  const calculateCartSubtotal = () => {
    return state.cart.reduce((total, item) => {
      return total + getValidPrice(item) * item.quantity;
    }, 0);
  };

  const validateForm = () => {
    const newErrors: any = {};
    if (!formData.firstName) newErrors.firstName = "*required";
    if (!formData.lastName) newErrors.lastName = "*required";
    if (!formData.state) newErrors.state = "*required";
    if (!formData.city) newErrors.city = "*required";
    if (!formData.zipCode) newErrors.zipCode = "*required";
    if (!formData.address) newErrors.address = "*required";
    if (!formData.phone) newErrors.phone = "*required";
    if (!formData.email) newErrors.email = "*required";
    if (formData.shipToDifferent) {
      if (!formData.secondary.city) newErrors["secondary.city"] = "*required";
      if (!formData.secondary.zipCode) newErrors["secondary.zipCode"] = "*required";
      if (!formData.secondary.address) newErrors["secondary.address"] = "*required";
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleConfirmAddress = (e) => {
    if (MANUAL) return;
    e.preventDefault();
    if (!validateForm()) return;
    // fetch shipping via API if MANUAL = false
  };

  const handleSubmit = async (e) => {
  e.preventDefault();
  if (!validateForm()) return;

  setIsSubmitting(true);
  setButtonDisabled(true);
  setTimeout(() => setButtonDisabled(false), 10000); // Re-enable after 10 seconds

  const stripePayload = {
    cart: state.cart.map(item => ({ 
      id: item.id, 
      quantity: item.quantity,
      metadata : { options : item.options }
    })),
    shipping: {
      email: formData.email,
      boxSize: "",
      shippingCost,
      trackingNumber: "",
      address: {
        firstName: formData.firstName,
        lastName: formData.lastName,
        line1: formData.address,
        line2: formData.address_2,
        city: formData.city,
        state: convertStateNameToAbbreviation(formData.state),
        zip: formData.zipCode,
        phone: formData.phone
      }
    }
  };

  try {
    const res = await fetch("https://stripe-msb-manual.makethemcall.workers.dev/portal", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(stripePayload),
    });
    const data = await res.json();
    // if (data?.url) navigate(data.url);
    // else console.error("No Stripe URL returned.");
    console.log(data);


  } catch (err) {
    console.error("Stripe error:", err);
  } finally {
    setIsSubmitting(false); // hide spinner regardless of success/failure
  }
};


  const getValidPrice = (item) => {
    const sale = parseFloat(item.sale_price);
    const regular = parseFloat(item.regular_price);
    return !isNaN(sale) && sale > 0 ? sale : !isNaN(regular) ? regular : 0;
  };

  return (
    <div className="checkout-container">
      <header className="checkout-header container">
        <h1>Checkout</h1>
        <nav className="breadcrumb">
          <span className="home-link">Home</span>
          <span className="separator">›</span>
          <span className="current">Checkout</span>
        </nav>
      </header>

      <div className="checkout-content container">
        <form onSubmit={handleSubmit} className="billing-form">
          <div className="form-row">
            <div className="form-group">
              <input name="firstName" placeholder="First name**" value={formData.firstName} onChange={handleInputChange} />
              {errors.firstName && <span className="error-text">{errors.firstName}</span>}
            </div>
            <div className="form-group">
              <input name="lastName" placeholder="Last name**" value={formData.lastName} onChange={handleInputChange} />
              {errors.lastName && <span className="error-text">{errors.lastName}</span>}
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <input name="phone" placeholder="Phone Number**" value={formData.phone} onChange={handleInputChange} />
              {errors.phone && <span className="error-text">{errors.phone}</span>}
            </div>
            <div className="form-group">
              <input name="email" type="email" placeholder="Email Address**" value={formData.email} onChange={handleInputChange} />
              {errors.email && <span className="error-text">{errors.email}</span>}
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <input value="United States" disabled />
            </div>
            <div className="form-group">
              <select name="state" value={formData.state} onChange={handleInputChange}>
                <option value="">Select State</option>
                {usStates.map(state => (
                  <option key={state} value={state}>{state}</option>
                ))}
              </select>
              {errors.state && <span className="error-text">{errors.state}</span>}
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <input name="city" placeholder="City**" value={formData.city} onChange={handleInputChange} />
              {errors.city && <span className="error-text">{errors.city}</span>}
            </div>
            <div className="form-group">
              <input name="zipCode" placeholder="Zip Code**" value={formData.zipCode} onChange={handleInputChange} />
              {errors.zipCode && <span className="error-text">{errors.zipCode}</span>}
            </div>
          </div>

          <div className="form-group">
            <input name="address" placeholder="Street Address**" value={formData.address} onChange={handleInputChange} />
            {errors.address && <span className="error-text">{errors.address}</span>}
          </div>
          <div className="form-group">
            <input name="address_2" placeholder="Apt, suite, etc. (optional)" value={formData.address_2} onChange={handleInputChange} />
          </div>

          <div className="payment-section">
            <img src={stripeLogo} alt="Powered by Stripe" style={{ width: "150px", marginTop: "20px" }} />
          </div>
        </form>

        <div className="order-summary">
          <div className="summary-header">
            <span className="product-title">Product</span>
            <span className="subtotal-title">Subtotal</span>
          </div>

          {state.cart.length > 0 ? (
            state.cart.map(item => (
              <div className="summary-item" key={item.id}>
                <span className="product-name-checkout">{item.name}</span>
                <span className="product-price">
                  ${(getValidPrice(item) * item.quantity).toFixed(2)}
                </span>
              </div>
            ))
          ) : (
            <div className="summary-item">
              <span className="product-name-checkout">No Products in Cart</span>
              <span className="product-price">$0.00</span>
            </div>
          )}

          {!MANUAL && (
            <div className="summary-row subtotal-row">
              <span className="subtotal-label">Subtotal</span>
              <span className="subtotal-amount">
               ${calculateCartSubtotal().toFixed(2)}
              </span>
            </div>
          )}

          {!MANUAL && (
            <button
              type="submit"
              disabled={addressConfirmed}
              style={{
                opacity: addressConfirmed ? 0.75 : 1.0,
                backgroundColor: addressConfirmed ? '#4caf50' : '#003144'
              }}
              className="place-order-btn"
              onClick={handleConfirmAddress}
            >
              {confirmingAddress ? "Checking Address" : addressConfirmed ? "Address Confirmed" : "Confirm Address"}
            </button>
          )}

          <div className="summary-row total-row" style={{ border: '0px solid transparent' }}>
            <span className="subtotal-label">Shipping</span>
            <span className="subtotal-amount">
              ${shippingCost.toFixed(2)}
            </span>
          </div>

          <div className="summary-row total-row">
            <span className="total-label">Total</span>
           <span className="total-amount">
  ${(shippingCost + calculateCartSubtotal()).toFixed(2)}
</span>
          </div>
          <button
            style={{ backgroundColor: MANUAL || addressConfirmed ? '#FF9900' : 'rgba(0,0,0,0.25)' }}
            disabled={!MANUAL && !addressConfirmed || buttonDisabled}
            type="submit"
            className="place-order-btn"
            onClick={handleSubmit}
          >
            {isSubmitting ? (
              <span className="spinner" style={{ display: 'inline-block', width: '18px', height: '18px', border: '3px solid white', borderTop: '3px solid transparent', borderRadius: '50%', animation: 'spin 1s linear infinite' }}></span>
            ) : (
              "Place Order"
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

export default CheckoutPageTest;
